#!/usr/bin/env bash
# VPN NUSANTARA installer bootstrap
# Seluruh isi installer utama disimpan dalam payload Base64.
set -Eeuo pipefail

if ! command -v base64 >/dev/null 2>&1; then
  echo "ERROR: utilitas base64 tidak ditemukan. Pasang coreutils terlebih dahulu." >&2
  exit 1
fi

tmp_file="$(mktemp "${TMPDIR:-/tmp}/vpn-nusantara-installer.XXXXXX")"
cleanup() { rm -f "$tmp_file"; }
trap cleanup EXIT HUP INT TERM

if ! printf '%s' \
  '' | base64 --decode > "$tmp_file"; then
  echo "ERROR: gagal mendekode payload installer." >&2
  exit 1
fi

bash "$tmp_file" "$@"
